.dm-abx-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@container (max-width:600px){.dm-abx-g{grid-template-columns:minmax(0,1fr)}.dm-abx-c{border-left:0;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);min-height:220px}}
/* on a phone the state takes its own line over the buttons, so Live with its avatar never pushes Publish out of the card */
@container (max-width:340px){.dm-abx-bar{flex-wrap:wrap;row-gap:var(--dm-s-2)}.dm-abx-st{flex-basis:100%}}

